using System;
using System.Drawing;
using System.Windows.Forms;
namespace ImageNdi {
public partial class MainWindow {
 readonly CheckBox videoLoop=new CheckBox{Name="VideoLoop",Text="Loop video",AutoSize=true,Enabled=false};
 readonly Label videoStatus=new Label{Name="VideoStatus",AutoSize=true};
 readonly VideoTransportBar previewTransport=new VideoTransportBar{Name="PreviewVideoTransport",Dock=DockStyle.Right};readonly VideoTransportBar programTransport=new VideoTransportBar{Name="ProgramVideoTransport",Dock=DockStyle.Right};
 VideoSession selectionVideo;long selectionVideoSequence;bool videoPending;DateTime videoDue;
 readonly NumericUpDown videoSpeed=new NumericUpDown{Name="VideoSpeed",Minimum=.5m,Maximum=5m,Increment=.1m,DecimalPlaces=1,Value=1,Width=72,Enabled=false,AccessibleName="Velocità video"};bool loadingSpeed;
 double SpeedFor(string path){double value;return path!=null&&settings.VideoSpeeds.TryGetValue(path,out value)?value:1;}
 void LoadVideoSpeed(){loadingSpeed=true;try{videoSpeed.Enabled=VideoTools.IsVideo(selected);videoSpeed.Value=(decimal)Math.Max(.5,Math.Min(5,SpeedFor(selected)));}finally{loadingSpeed=false;}}
 void InitializeVideo(Control bar){bar.Height=100;var row=new FlowLayoutPanel{Name="VideoControls",Width=1000,Height=34,AutoScroll=true};bar.Controls.Add(row);row.Controls.Add(videoLoop);row.Controls.Add(videoStatus);videoLoop.CheckedChanged+=delegate{if(!loading&&VideoTools.IsVideo(selected))ApplyPlacement(PlacementNow(),true);};previewTransport.PlayPauseRequested+=delegate{ToggleVideo(false);};programTransport.PlayPauseRequested+=delegate{ToggleVideo(true);};previewTransport.RestartRequested+=delegate{RestartVideo(false,null);};programTransport.RestartRequested+=delegate{RestartVideo(true,null);};videoSpeed.ValueChanged+=delegate{if(loadingSpeed||selected==null||!VideoTools.IsVideo(selected))return;double speed=(double)videoSpeed.Value;settings.VideoSpeeds[selected]=speed;mutePreview.Checked=true;if(selectionVideo!=null)RestartVideo(false,speed);Save();};Disposed+=delegate{StopSelectionVideo();};}
 void StopSelectionVideo(){videoPending=false;if(selectionVideo!=null){selectionVideo.Dispose();selectionVideo=null;}selectionVideoSequence=0;previewTransport.SetVideo(null);}
 void ScheduleSelectionVideo(){videoLoop.Enabled=VideoTools.IsVideo(selected);if(videoLoop.Enabled&&pending!=null){videoPending=true;videoDue=DateTime.UtcNow.AddMilliseconds(150);}}
 void StartSelectionVideo(){StopSelectionVideo();videoLoop.Enabled=VideoTools.IsVideo(selected);if(!videoLoop.Enabled||pending==null)return;selectionVideo=new VideoSession(selected,FrameWidth,FrameHeight,output==null?previewOutput==null?(int)fps.Value:previewFps:activeProgramFps,PlacementNow(),videoLoop.Checked,pending,PreviewAudio,GainFor(selected),SpeedFor(selected));selectionVideo.ActivateAudio(0);PublishPreview();previewTransport.SetVideo(selectionVideo);}
 void ToggleVideo(bool onProgram){var video=onProgram?(output==null?null:output.CurrentVideo):selectionVideo;if(video==null)return;if(video.Ended&&!video.Paused){RestartVideo(onProgram,null);return;}video.SetPaused(!video.Paused);(onProgram?programTransport:previewTransport).SetVideo(video);}
 void RestartVideo(bool onProgram,double? newSpeed){var video=onProgram?(output==null?null:output.CurrentVideo):selectionVideo;if(video==null)return;VideoSession replacement=null;bool adopted=false;try{double speed=newSpeed??video.Speed;replacement=video.Restart(speed,video.Paused,GainFor(video.Path));if(onProgram){output.CueSource(replacement,replacement.ReadFrame(),0,video.Path);adopted=true;}else{replacement.ActivateAudio(0);selectionVideo=replacement;adopted=true;selectionVideoSequence=0;video.Dispose();pending=replacement.ReadFrame();preview.SetFrame(Renderer.ToBitmap(pending,FrameWidth,FrameHeight),FrameWidth,FrameHeight);PublishPreview();}(onProgram?programTransport:previewTransport).SetVideo(replacement);}catch(Exception e){status.Text="Controllo video: "+e.Message;MessageBox.Show(e.Message,"Controllo video");(onProgram?programTransport:previewTransport).SetVideo(onProgram?(output==null?null:output.CurrentVideo):selectionVideo);}finally{if(!adopted&&replacement!=null)replacement.Dispose();}}
 void UpdateSelectionVideo(){programTransport.SetVideo(output==null?null:output.CurrentVideo);if(videoPending&&DateTime.UtcNow>=videoDue){try{StartSelectionVideo();}catch(Exception e){videoStatus.Text=e.Message;return;}}if(selectionVideo==null){videoStatus.Text="";return;}previewTransport.SetVideo(selectionVideo);videoStatus.Text=selectionVideo.Error??(selectionVideo.Ended?"Video terminato · ultimo fotogramma":selectionVideo.Paused?"Video in pausa":videoLoop.Checked?"Video in loop · "+(PreviewAudio==null?"audio Preview spento":"audio Preview abilitato"):"Video in riproduzione · "+(PreviewAudio==null?"audio Preview spento":"audio Preview abilitato"));long sequence=System.Threading.Interlocked.Read(ref selectionVideo.DecodedFrames);if(sequence==selectionVideoSequence)return;selectionVideoSequence=sequence;pending=selectionVideo.ReadFrame();preview.SetFrame(Renderer.ToBitmap(pending,FrameWidth,FrameHeight),FrameWidth,FrameHeight);}
}
}
